const TAB = (head: string[], rows: (string | number)[][]) => '<div class="lw"><table class="lta"><tr>' + head.map(h => "<th>" + h + "</th>").join("") + "</tr>" + rows.map(r => "<tr>" + r.map(c => "<td>" + c + "</td>").join("") + "</tr>").join("") + "</table></div>";

