function svgViereck() {
  const box = (x: number, y: number, t1: string, t2: string) => '<rect class="la" x="' + x + '" y="' + y + '" width="128" height="40" rx="8" fill="none"/><text class="lt" x="' + (x + 64) + '" y="' + (y + 17) + '" text-anchor="middle">' + t1 + '</text><text x="' + (x + 64) + '" y="' + (y + 32) + '" text-anchor="middle">' + t2 + '</text>';
  return '<svg class="lfig" viewBox="0 0 340 220" role="img" aria-label="Magisches Viereck mit vier Zielen und zwei Erweiterungen zum Sechseck">' +
    box(6, 8, "Preisniveau-", "stabilität") + box(206, 8, "hoher Beschäf-", "tigungsstand") + box(6, 132, "stetiges, angem.", "Wachstum") + box(206, 132, "außenwirtschaftl.", "Gleichgewicht") +
    '<rect x="125" y="78" width="90" height="44" rx="6" style="fill:var(--accent);opacity:.18"/><text class="lt" x="170" y="97" text-anchor="middle">magisches</text><text class="lt" x="170" y="112" text-anchor="middle">Viereck</text>' +
    '<line class="lh" x1="134" y1="48" x2="150" y2="78"/><line class="lh" x1="206" y1="48" x2="190" y2="78"/><line class="lh" x1="134" y1="132" x2="150" y2="122"/><line class="lh" x1="206" y1="132" x2="190" y2="122"/>' +
    '<text x="170" y="196" text-anchor="middle">Sechseck: + lebenswerte Umwelt</text><text x="170" y="212" text-anchor="middle">+ gerechte Einkommens- und Vermögensverteilung</text></svg>';
}

