export const WL_EXAM: ExamTask[] = [
 { n: 1, title: "Soziale Marktwirtschaft", p: 6, q: "a) Erläutern Sie die Grundidee der Sozialen Marktwirtschaft und grenzen Sie sie von der freien Marktwirtschaft ab.<br>b) Erklären Sie an zwei Ordnungsmerkmalen, wie das Grundgesetz Freiheit gewährt und zugleich begrenzt. Nennen Sie die Artikel.", s: "a) So viel Freiheit wie möglich, so viel staatlicher Zwang wie nötig (Ludwig Erhard). Freier Markt mit Preisbildung über Angebot und Nachfrage, aber der Staat setzt den Rahmen und sorgt für sozialen Ausgleich. Die freie Marktwirtschaft verzichtet auf Staatseingriffe (2 P).<br>b) z. B. Berufsfreiheit (Art. 12), begrenzt durch Zulassungen wie die Approbation. Eigentum (Art. 14), begrenzt durch die Sozialbindung und mögliche Enteignung zum Wohl der Allgemeinheit (je 2 P)." },
 { n: 2, title: "Tarifrecht", p: 8, q: "Die Tarifverhandlungen zwischen IG Metall und Südwestmetall sind gescheitert.<br>a) Beschreiben Sie den weiteren Ablauf bis zu einem neuen Tarifvertrag.<br>b) Erklären Sie die Begriffe Friedenspflicht und Günstigkeitsprinzip.<br>c) Der Arbeitgeber von Frau Kaya ist nicht im Arbeitgeberverband. Prüfen Sie, ob die neue Lohnerhöhung trotzdem für sie gelten kann.", s: "a) evtl. Schlichtung, Urabstimmung über Streik (75 %), Streik und evtl. Aussperrung, neue Verhandlungen, Urabstimmung über das Ergebnis (25 %), neuer Tarifvertrag (3 P).<br>b) Friedenspflicht: kein Arbeitskampf während der Laufzeit über geregelte Punkte. Günstigkeitsprinzip: Abweichungen nur zugunsten des Arbeitnehmers (2 P).<br>c) Ohne Verbandsmitgliedschaft keine Tarifbindung. Gelten kann der Vertrag trotzdem, wenn er für allgemeinverbindlich erklärt wurde oder ihr Arbeitsvertrag auf ihn verweist (3 P)." },
 { n: 3, title: "Wettbewerbspolitik", p: 6, q: "Zwei große Lebensmittelhändler wollen fusionieren.<br>a) Erklären Sie den Unterschied zwischen Fusion, Konzern und Kartell.<br>b) Begründen Sie, warum das Bundeskartellamt den Zusammenschluss prüft, und nennen Sie die gesetzliche Grundlage.", s: "a) Fusion: Verschmelzung, rechtliche und wirtschaftliche Selbstständigkeit gehen verloren. Konzern: rechtlich selbstständig, aber einheitliche Leitung. Kartell: Absprache selbstständiger Unternehmen, grundsätzlich verboten (3 P).<br>b) Horizontaler Zusammenschluss, große Marktmacht kann den Wettbewerb erheblich behindern: höhere Preise für Kunden, schlechtere Bedingungen für Lieferanten. Fusionskontrolle nach dem GWB (3 P)." },
 { n: 4, title: "Steuern", p: 6, q: "Herr Brandt tankt, kauft Zigaretten und erhält seine Gehaltsabrechnung mit Lohn- und Kirchensteuer. Seine GmbH zahlt Körperschaftsteuer.<br>a) Ordnen Sie die vier Steuern nach dem Steuergegenstand.<br>b) Unterscheiden Sie direkte und indirekte Steuern und ordnen Sie zu.<br>c) Erklären Sie den Unterschied zwischen Staatsdefizit und Staatsverschuldung.", s: "a) Besitzsteuern: Lohn-, Kirchen-, Körperschaftsteuer. Verbrauchsteuern: Energiesteuer auf Benzin, Tabaksteuer (2 P).<br>b) Direkt (Schuldner = Träger): Lohn-, Kirchen-, Körperschaftsteuer. Indirekt (Überwälzung auf den Verbraucher): Energie-, Tabaksteuer, auch die Umsatzsteuer (2 P).<br>c) Defizit: Ausgaben eines Jahres übersteigen die Einnahmen. Verschuldung: Summe aller Schulden (2 P)." },
 { n: 5, title: "Preisbildung an der Börse", p: 10, q: "An einer Warenbörse für Bio-Hafer liegen folgende Aufträge vor (Preis je dt):<br>Verkäufer: V1 300 dt ab 20 €, V2 200 dt ab 22 €, V3 100 dt ab 24 €, V4 300 dt ab 26 €.<br>Käufer: K1 200 dt bis 26 €, K2 400 dt bis 24 €, K3 400 dt bis 22 €, K4 300 dt bis 20 €.<br>a) Ermitteln Sie in einer Tabelle für 20, 22, 24 und 26 € Gesamtangebot, Gesamtnachfrage und umgesetzte Menge.<br>b) Geben Sie Gleichgewichtspreis und -menge an und nennen Sie die Marktteilnehmer, die nicht zum Zug kommen.<br>c) Beschreiben Sie die Marktsituation bei 22 €.<br>d) Berechnen Sie die Produzentenrente von V1 und die Konsumentenrente von K1.", s: "a) 20 €: A 300, N 1.300, umgesetzt 300. 22 €: A 500, N 1.000, umgesetzt 500. 24 €: A 600, N 600, umgesetzt 600. 26 €: A 900, N 200, umgesetzt 200 (4 P).<br>b) 24 €, 600 dt. Nicht zum Zug: V4 (verlangt mehr), K3 und K4 (wollen weniger zahlen) (2 P).<br>c) N 1.000 > A 500: Nachfrageüberschuss (Angebotslücke) von 500 dt, der Preis steigt (2 P).<br>d) V1: (24 − 20) · 300 = 1.200 €. K1: (26 − 24) · 200 = 400 € (2 P)." },
 { n: 6, title: "Preismechanismus", p: 5, q: "Wegen einer Dürre fällt die Haferernte schlecht aus. Gleichzeitig wird Haferdrink immer beliebter.<br>a) Stellen Sie beide Veränderungen in einem Preis-Mengen-Diagramm dar.<br>b) Erläutern Sie die Wirkung auf Gleichgewichtspreis und -menge.", s: "a) Angebotskurve nach links, Nachfragekurve nach rechts, neuer Schnittpunkt höher (2 P).<br>b) Beide Effekte erhöhen den Preis, er steigt sicher. Die Menge sinkt durch das geringere Angebot und steigt durch die höhere Nachfrage, die Wirkung ist unbestimmt (3 P)." },
 { n: 7, title: "Staatseingriffe", p: 7, q: "Wegen stark steigender Mieten fordert eine Partei eine feste Obergrenze für Mieten.<br>a) Ordnen Sie die Maßnahme ein (marktkonform oder marktkonträr) und begründen Sie.<br>b) Stellen Sie die Maßnahme in einem Diagramm dar.<br>c) Beurteilen Sie die Maßnahme mit zwei Folgen und schlagen Sie einen marktkonformen Eingriff vor.", s: "a) Höchstpreis, marktkonträr, der Preismechanismus wird außer Kraft gesetzt (2 P).<br>b) Waagrechte Linie unter p*, Nachfrageüberschuss zwischen A und N beschriftet (2 P).<br>c) + Mieter mit Wohnung zahlen weniger. − Wohnungsmangel, Schwarzmarkt, weniger Neubau und Instandhaltung. Marktkonform: Förderung des Wohnungsbaus (A nach rechts) oder Wohngeld (N nach rechts) (3 P)." },
 { n: 8, title: "Magisches Viereck", p: 6, q: "a) Nennen Sie die vier Ziele des Stabilitätsgesetzes und je eine Messgröße.<br>b) Erklären Sie, warum man vom „magischen“ Viereck spricht, an einem Zielkonflikt.<br>c) Nennen Sie die beiden Ziele, um die es zum Sechseck erweitert wurde.", s: "a) Preisniveaustabilität (Inflationsrate), hoher Beschäftigungsstand (Arbeitslosenquote), stetiges und angemessenes Wachstum (reales BIP), außenwirtschaftliches Gleichgewicht (Außenbeitrag/Leistungsbilanz) (2 P).<br>b) Nicht alle Ziele gleichzeitig erreichbar. z. B. Vollbeschäftigung durch höhere Staatsausgaben erhöht die Nachfrage und gefährdet die Preisniveaustabilität (2 P).<br>c) Erhalt einer lebenswerten Umwelt, gerechte Einkommens- und Vermögensverteilung (2 P)." }
];

